sp_widget.client_script:
api.controller = function() {
    var c = this;

    c.getBarWidth = function(count, max) {
        if (!max || max === 0) return '0%';
        return Math.round((count / max) * 100) + '%';
    };
};

sp_widget.css:
.sp-bar-row {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 12px;
}
.sp-bar-label {
    font-size: $font-size-small;
    color: $text-color;
    min-width: 100px;
    flex-shrink: 0;
}
.sp-bar-track {
    flex: 1;
    height: 20px;
    background: $background-secondary;
    border-radius: $border-radius-base;
    overflow: hidden;
}
.sp-bar-fill {
    height: 100%;
    border-radius: $border-radius-base;
    transition: width 0.3s ease;
    min-width: 2px;
}
.sp-bar-info {
    background: $brand-info;
}
.sp-bar-warning {
    background: $brand-warning;
}
.sp-bar-success {
    background: $brand-success;
}
.sp-bar-primary {
    background: $brand-primary;
}
.sp-bar-count {
    font-size: $font-size-small;
    font-weight: 600;
    color: $text-muted;
    min-width: 30px;
    text-align: right;
}

sp_widget.script:
(function() {
    var table = 'x_839216_public_0_health_service_request_v1';
    data.statusDist = [];
    data.priorityDist = [];
    data.typeDist = [];
    data.groupDist = [];

    var statusMap = {};
    var priorityMap = {};
    var typeMap = {};
    var groupMap = {};

    var gr = new GlideRecord(table);
    gr.setLimit(500);
    gr.query();
    while (gr.next()) {
        var status = gr.getDisplayValue('u_status') + '';
        var priority = gr.getDisplayValue('u_priority') + '';
        var reqType = gr.getDisplayValue('u_request_type') + '';
        var group = gr.getDisplayValue('assignment_group') + '';

        statusMap[status] = (statusMap[status] || 0) + 1;
        priorityMap[priority] = (priorityMap[priority] || 0) + 1;
        typeMap[reqType] = (typeMap[reqType] || 0) + 1;
        if (group) {
            groupMap[group] = (groupMap[group] || 0) + 1;
        }
    }

    for (var s in statusMap) {
        data.statusDist.push({label: s, count: statusMap[s]});
    }
    for (var p in priorityMap) {
        data.priorityDist.push({label: p, count: priorityMap[p]});
    }
    for (var t in typeMap) {
        data.typeDist.push({label: t, count: typeMap[t]});
    }
    for (var g in groupMap) {
        data.groupDist.push({label: g, count: groupMap[g]});
    }

    data.maxStatus = 0;
    data.maxPriority = 0;
    data.maxType = 0;
    data.maxGroup = 0;
    for (var i = 0; i < data.statusDist.length; i++) {
        if (data.statusDist[i].count > data.maxStatus) data.maxStatus = data.statusDist[i].count;
    }
    for (var j = 0; j < data.priorityDist.length; j++) {
        if (data.priorityDist[j].count > data.maxPriority) data.maxPriority = data.priorityDist[j].count;
    }
    for (var k = 0; k < data.typeDist.length; k++) {
        if (data.typeDist[k].count > data.maxType) data.maxType = data.typeDist[k].count;
    }
    for (var l = 0; l < data.groupDist.length; l++) {
        if (data.groupDist[l].count > data.maxGroup) data.maxGroup = data.groupDist[l].count;
    }
})();
